    irmasT(t).filter(z=>z!==t).forEach(z=>{let Lz=[];try{Lz=_lA.call(this,z,a)}catch(_){}Lz.forEach(x=>{if(M[g+'|'+x.k]===t.id&&!R.some(y=>y.k===x.k))R.push({...x,mov:z.id})})});
