/* aplica (ou atualiza) o modelo a um módulo; elems=[{id,tipo,peso}] (soma 70) */
function profAplicar(t,m,elems){if(!t.porModulo){try{modAtivar(t)}catch(e){console.warn(e)}}
  m.av=m.av||{dominios:[],mencoes:(t.__mod||t).mencoes||MENCOES_DEF.map(x=>({...x})),regra:{2:'media',3:'media'},instrumentos:[]};const av=m.av;av.instrumentos=av.instrumentos||[];
  elems=(elems||(av.prof&&av.prof.elems)||[{id:'e'+uid(),tipo:'Trabalho Prático',peso:40},{id:'e'+uid(),tipo:'Teste Escrito',peso:30}]).map(e=>({id:e.id||'e'+uid(),tipo:e.tipo||'Outros',peso:+e.peso||0}));
  av.prof={v:1,elems};
  const D=[];PROF_ATIT.forEach(g=>D.push({id:'pa_'+g.k,ab:g.ab,nome:g.nome,peso:g.peso,grupo:'Saber Estar'}));
  const ab=x=>({'Trabalho Prático':'TP','Teste Escrito':'TE','Teste Oral':'TO','Trabalho de Grupo':'TG','Trabalho Individual':'TI'}[x]||'OU');
  const usados={};elems.forEach(e=>{let a=ab(e.tipo);usados[a]=(usados[a]||0)+1;if(usados[a]>1)a+=usados[a];D.push({id:'pf_'+e.id,ab:a,nome:e.tipo,peso:e.peso,grupo:'Saber Fazer'})});
  av.dominios=D;
  /* instrumento das atitudes (18 indicadores) */
  let ia=av.instrumentos.find(i=>i.profAtt);if(!ia){ia={id:'att'+uid(),nome:'Atitudes e Valores — Saber Estar',tipo:'Observação em Sala de Aula',periodo:1,data:isoData(new Date()),itens:[],notas:{},profAtt:true,modulo:m.id};av.instrumentos.unshift(ia)}
  ia.itens=profIndList().map((x,q)=>{const ant=(ia.itens||[])[q];return {id:ant&&ant.id||('ai'+q+uid().slice(0,5)),rot:x.n,dom:'pa_'+x.g.k,cot:20}});
  /* um instrumento por elemento */
  elems.forEach(e=>{const dom='pf_'+e.id;if(av.instrumentos.some(i=>i.profElem===e.id||(i.itens||[]).some(it=>it.dom===dom)))return;
    const i={id:'pe'+uid(),nome:e.tipo,tipo:e.tipo==='Teste Escrito'?'Teste de Avaliação':e.tipo==='Teste Oral'?'Apresentação Oral':e.tipo==='Trabalho Prático'?'Trabalho Prático':e.tipo,periodo:1,data:isoData(new Date()),notas:{},profElem:e.id,modulo:m.id,
      itens:e.tipo==='Trabalho Prático'?PROF_TP.map(([n,c],q)=>({id:'tp'+q+uid().slice(0,5),rot:'Ponto '+(q+1)+' — '+n,dom,cot:c})):[{id:'it'+uid(),rot:'Classificação (0–20)',dom,cot:20}]};av.instrumentos.push(i)});
  /* elementos retirados: domínio deixa de existir; instrumentos sem notas saem */
  const vivos=new Set(D.map(d=>d.id));av.instrumentos=av.instrumentos.filter(i=>{if(i.profAtt)return true;const doms=(i.itens||[]).map(x=>x.dom);if(doms.every(d=>vivos.has(d)))return true;const tem=Object.values(i.notas||{}).some(n=>Object.keys(n||{}).length);if(!tem&&i.profElem)return false;const sf=D.find(d=>d.grupo==='Saber Fazer')||D[D.length-1];i.itens.forEach(x=>{if(!vivos.has(x.dom))x.dom=sf.id});return true});
  save();return m}
/* atitudes: como na grelha, cada área = média arredondada dos indicadores */
{const _iDp=instDom;instDom=function(i,aid,dom){if(i&&i.profAtt){const n=(i.notas||{})[aid];if(!n)return null;const its=i.itens.filter(x=>x.dom===dom);const v=its.map(x=>num(n[x.id])).filter(x=>x!=null);if(!v.length)return null;const md=Math.round(v.reduce((a,b)=>a+b,0)/v.length);return {pts:md,max:20,pct:md/20}}return _iDp.apply(this,arguments)}}
function profAreaVal(t,m,aid,domId){const I=(m.av.instrumentos||[]);const v=I.map(i=>instDom(i,aid,domId)).filter(Boolean).map(x=>x.pct);return v.length?v.reduce((a,b)=>a+b,0)/v.length*20:null}
function profNotaDec(t,m,aid){const D=m.av.dominios||[];let s=0,w=0;D.forEach(d=>{const v=profAreaVal(t,m,aid,d.id);if(v!=null&&+d.peso>0){s+=v*d.peso;w+=+d.peso}});return w?s/w:null}
